const pendingApprovalDocs = `-- name: PendingApprovalDocs :many

WITH docs AS (
    SELECT 'PR'::text AS doc_type, r.id, r.request_number AS number, r.est_total, r.department_id, r.requester_id, r.submitted_at, r.cycle
      FROM inv_requests r WHERE r.tenant_id = $1 AND r.property_id = $2 AND r.status = 'SUBMITTED'
    UNION ALL
    SELECT 'SR'::text, r.id, r.sr_number, r.est_total, r.department_id, r.requester_id, r.submitted_at, r.cycle
      FROM inv_requisitions r WHERE r.tenant_id = $1 AND r.property_id = $2 AND r.status = 'SUBMITTED'
)
SELECT d.doc_type, d.id, d.number, d.est_total, d.department_id, COALESCE(dep.name, '')::text AS department_name, d.requester_id, COALESCE(u.full_name, '')::text AS requester_name, d.submitted_at,
       s.level_no, s.name AS step_name, s.approver_kind, s.permission, s.activated_at,
       COALESCE(CASE s.approver_kind
           WHEN 'PERMISSION' THEN (SELECT string_agg(DISTINCT x.full_name, ', ') FROM users x
                                    WHERE x.tenant_id = $1 AND x.is_active AND x.id <> d.requester_id
                                      AND (x.is_tenant_admin OR EXISTS (SELECT 1 FROM user_properties up JOIN role_permissions rp ON rp.role_id = up.role_id
                                                                         WHERE up.tenant_id = $1 AND up.user_id = x.id AND up.property_id = $2 AND rp.permission_code = s.permission)))
           ELSE (SELECT string_agg(DISTINCT x.full_name, ', ') FROM users x
                  WHERE x.tenant_id = $1 AND x.is_active AND x.id <> d.requester_id
                    AND x.id IN (CASE WHEN dep.head_user_id IS NOT NULL THEN dep.head_user_id ELSE pd.head_user_id END, CASE WHEN dep.head_user_id IS NOT NULL THEN dep.deputy_user_id ELSE pd.deputy_user_id END))
       END, '')::text AS awaiting
  FROM docs d
  JOIN inv_approval_steps s ON s.property_id = $2 AND s.cycle = d.cycle AND s.status = 'ACTIVE'
                           AND ((d.doc_type = 'PR' AND s.request_id = d.id) OR (d.doc_type = 'SR' AND s.requisition_id = d.id))
  LEFT JOIN users u ON u.tenant_id = $1 AND u.id = d.requester_id
  LEFT JOIN departments dep ON dep.property_id = $2 AND dep.id = d.department_id
  LEFT JOIN departments pd ON pd.property_id = $2 AND pd.id = dep.parent_id
 ORDER BY COALESCE(s.activated_at, d.submitted_at), d.id
`

type PendingApprovalDocsParams struct {
	TenantID   int64
	PropertyID int64
}

type PendingApprovalDocsRow struct {
	DocType        string
	ID             int64
	Number         string
	EstTotal       decimal.Decimal
	DepartmentID   *int64
	DepartmentName string
	RequesterID    int64
	RequesterName  string
	SubmittedAt    *time.Time
	LevelNo        int16
	StepName       string
	ApproverKind   string
	Permission     *string
	ActivatedAt    *time.Time
	Awaiting       string
}

// ---------------------------------------------------------------------------------------------------------------------
// Documents waiting in the approval chain (A6): the purchase requests and the requisitions that are still in the chain, with the level that holds them and who may decide it.
// The age counts from the moment the current level was reached (activated_at), not from the submission.
func (q *Queries) PendingApprovalDocs(ctx context.Context, arg PendingApprovalDocsParams) ([]PendingApprovalDocsRow, error) {
	rows, err := q.db.Query(ctx, pendingApprovalDocs, arg.TenantID, arg.PropertyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PendingApprovalDocsRow{}
	for rows.Next() {
		var i PendingApprovalDocsRow
		if err := rows.Scan(
			&i.DocType,
			&i.ID,
			&i.Number,
			&i.EstTotal,
			&i.DepartmentID,
			&i.DepartmentName,
			&i.RequesterID,
			&i.RequesterName,
			&i.SubmittedAt,
			&i.LevelNo,
			&i.StepName,
			&i.ApproverKind,
			&i.Permission,
			&i.ActivatedAt,
			&i.Awaiting,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

